using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class FixImpactShards
{
 const string Mod="Assets/Blueprinter/Mods/Gunmageddon/",Dir=Mod+"ImpactShards/";
 public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");if(AssetDatabase.IsValidFolder(Dir.TrimEnd('/')))throw new Exception("Owned shards already exist");Directory.CreateDirectory(Path.Combine(Application.dataPath,"BlueprinterSetupBackups/ReleaseCheck"));AssetDatabase.Refresh();AssetDatabase.CreateFolder(Mod.TrimEnd('/'),"ImpactShards");var meshes=new Mesh[4];var sizes=new[]{new Vector3(.83f,.45f,1.05f),new Vector3(.61f,.24f,1.01f),new Vector3(.28f,.30f,1.11f),new Vector3(.39f,.14f,.64f)};for(int i=0;i<4;i++){// Original authored irregular shards, not copies of the native debris meshes.
  var mesh=new Mesh{name="Gunmaggedon_ImpactShard"+(i+1)};float k=i*.035f;var s=sizes[i];var vertices=new[]{new Vector3(-.5f,-.2f,-.5f),new Vector3(.4f,.12f,-.35f+k),new Vector3(.5f,-.3f,.2f),new Vector3(-.2f,-.5f,.5f),new Vector3(-.1f,.5f,.12f+k)}.Select(v=>Vector3.Scale(v,s)).ToArray();mesh.vertices=vertices;mesh.triangles=new[]{0,2,1,0,3,2,0,1,4,1,2,4,2,3,4,3,0,4};mesh.uv=new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up,new Vector2(.5f,.5f)};mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Dir+mesh.name+".asset");meshes[i]=mesh;}
  int systems=0;foreach(string name in new[]{"203mm_impactEffectArmor","203mm_impactEffectGround"}){string path=Mod+name+".prefab";if(!AssetDatabase.CopyAsset(path,"Assets/BlueprinterSetupBackups/ReleaseCheck/"+name+".prefab"))throw new Exception("Backup failed");var root=PrefabUtility.LoadPrefabContents(path);try{foreach(var renderer in root.GetComponentsInChildren<ParticleSystemRenderer>(true).Where(r=>r.name=="shrapnel")){renderer.SetMeshes(meshes);systems++;}PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
  AssetDatabase.SaveAssets();return new{systems,meshes=meshes.Length,trianglesEach=6,nativeGeometryCopied=false};}
}
